  for(const item of candidates){try{const p=await fetch('/api/admin/social/live-authorization',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({platform:item.platform,title:preset.title,description:quickDescription.value.trim(),format:preset.format})}),j=await p.json();if(!p.ok)throw Error(j?.error?.message||'Live preparation failed.');results.push({platform:item.platform,ok:true,provider_id:j.provider_id||null});}catch(e){results.push({platform:item.platform,ok:false,error:e.message});}}
